/* ----------------------------------------------------------------------------
 * BooKi - "İlk Müsaitlik" widget (2026-09-10, redesigned 2026-09-12, vertical-first 2026-09-28).
 *
 * Renders a horizontal strip of compact pills, one per provider / station, showing
 * next available time, window duration, and relevant vertical terminology.
 * Adapts dynamically to the active industry (Beauty, Restaurant, Clinic, Automotive, Sports, etc.).
 * ---------------------------------------------------------------------------- */
App.Components.NextAvailabilityWidget = (function () {
    const POLL_INTERVAL_MS = 60000;

    const mounts = []; // [{ $container, getProviderId }]

    /**
     * @returns {number|null} The selected provider's ID, or null if "Tümü"/a service is selected.
     */
    function getCalendarFilterProviderId() {
        const $selected = $('#select-filter-item option:selected');

        if ($selected.attr('type') !== 'provider') {
            return null;
        }

        return $selected.val();
    }

    function getVerticalTerms() {
        const terms = (window.vars && window.vars('terminology')) || {};
        const verticalGroup = (window.vars && window.vars('vertical_group')) || '';
        const industryCode = (window.vars && window.vars('industry_code')) || '';

        let providerRaw = terms.provider || terms.provider_label || 'Personel';
        let stationRaw = terms.station || terms.station_label || 'İstasyon / Oda';

        // Extract a clean short label for chips (e.g., "Personel / Uzman" -> "Uzman", "Kabin / Cihaz" -> "Kabin")
        let providerSingle = providerRaw;
        if (providerRaw.includes('/')) {
            const parts = providerRaw.split('/').map(s => s.trim());
            providerSingle = parts[1] || parts[0];
        }

        let stationSingle = stationRaw;
        if (stationRaw.includes('/')) {
            const parts = stationRaw.split('/').map(s => s.trim());
            stationSingle = parts[0] || parts[1];
        }

        // Plural / Group titles tailored to vertical
        let providerGroup = null;
        let stationGroup = null;

        if (/hekim|doktor|klinik|sağlık/i.test(industryCode + verticalGroup + providerRaw)) {
            providerGroup = 'Hekimler & Uzmanlar';
            stationGroup = 'Tedavi Odaları & Poliklinikler';
        } else if (/restoran|restaurant|cafe|lokanta|gıda/i.test(industryCode + verticalGroup)) {
            providerGroup = 'Servis & Salon Ekibi';
            stationGroup = 'Masalar & Bölümler';
        } else if (/oto|araç|car_wash|auto/i.test(industryCode + verticalGroup)) {
            providerGroup = 'Ustalar & Teknisyenler';
            stationGroup = 'Liftler & Çalışma İstasyonları';
        } else if (/spor|gym|pilates|fitness|kort/i.test(industryCode + verticalGroup)) {
            providerGroup = 'Eğitmenler & Koçlar';
            stationGroup = 'Kortlar, Sahalar & Alanlar';
        } else if (/kuaför|berber/i.test(industryCode + providerRaw)) {
            providerGroup = 'Kuaförler & Stilistler';
            stationGroup = 'Koltuklar & İstasyonlar';
        } else if (/güzellik|beauty|estetik|spa|masaj/i.test(industryCode + verticalGroup)) {
            providerGroup = 'Uzmanlar & Estetisyenler';
            stationGroup = 'Kabinler, Koltuklar & Odalar';
        } else {
            providerGroup = providerSingle + ' Müsaitliği';
            stationGroup = stationSingle + ' Durumu';
        }

        // Dynamic FontAwesome icons
        let providerIcon = 'fas fa-user-clock text-primary';
        let stationIcon = 'fas fa-door-open text-info';

        if (/hekim|doktor/i.test(providerRaw)) {
            providerIcon = 'fas fa-user-md text-primary';
        } else if (/usta|teknik/i.test(providerRaw)) {
            providerIcon = 'fas fa-tools text-primary';
        } else if (/eğitmen|koç/i.test(providerRaw)) {
            providerIcon = 'fas fa-dumbbell text-primary';
        } else if (/uzman|estetisyen|kuaför|terapist/i.test(providerRaw)) {
            providerIcon = 'fas fa-spa text-primary';
        }

        if (/masa/i.test(stationRaw)) {
            stationIcon = 'fas fa-utensils text-info';
        } else if (/kabin|cihaz|koltuk/i.test(stationRaw)) {
            stationIcon = 'fas fa-couch text-info';
        } else if (/lift|peron/i.test(stationRaw)) {
            stationIcon = 'fas fa-car text-info';
        } else if (/kort|saha|salon/i.test(stationRaw)) {
            stationIcon = 'fas fa-futbol text-info';
        }

        return {
            providerSingle,
            stationSingle,
            providerGroup,
            stationGroup,
            providerIcon,
            stationIcon
        };
    }

    function pillClass(row) {
        if (!row.available) {
            return 'kcc-availability-pill kcc-availability-pill-none';
        }

        if (row.is_now) {
            return 'kcc-availability-pill kcc-availability-pill-now';
        }

        if (Number.isFinite(row.window_minutes) && row.window_minutes < 20) {
            return 'kcc-availability-pill kcc-availability-pill-tight';
        }

        return 'kcc-availability-pill kcc-availability-pill-ok';
    }

    function renderProviderRow(row, terms) {
        const $pill = $('<div/>', { class: pillClass(row) });

        // Provider Name
        $pill.append(
            $('<span/>', { class: 'kcc-availability-field' })
                .append($('<span/>', { class: 'kcc-availability-field-label', text: terms.providerSingle }))
                .append($('<span/>', { class: 'kcc-availability-field-value', text: row.provider_name || '-' }))
        );

        // Station info (ONLY if present)
        if (row.station_name && row.station_name !== '-') {
            $pill.append(
                $('<span/>', { class: 'kcc-availability-field' })
                    .append($('<span/>', { class: 'kcc-availability-field-label', text: terms.stationSingle }))
                    .append($('<span/>', { class: 'kcc-availability-field-value', text: row.station_name }))
            );
        }

        if (!row.available) {
            $pill.append($('<span/>', { class: 'kcc-availability-time text-danger', text: 'Müsait Değil' }));
            return $pill;
        }

        $pill.append($('<span/>', { class: 'kcc-availability-time', text: row.is_now ? 'Şimdi Müsait' : row.time }));

        if (Number.isFinite(row.window_minutes)) {
            $pill.append($('<span/>', { class: 'kcc-availability-window', text: '~' + row.window_minutes + ' dk' }));
        }

        return $pill;
    }

    function renderStationRow(row, terms) {
        const $pill = $('<div/>', { class: pillClass(row) });

        // Station Name
        $pill.append(
            $('<span/>', { class: 'kcc-availability-field' })
                .append($('<span/>', { class: 'kcc-availability-field-label', text: terms.stationSingle }))
                .append($('<span/>', { class: 'kcc-availability-field-value', text: row.station_name || '-' }))
        );

        // Occupying Provider info (ONLY if occupied by someone right now)
        if (row.provider_name && row.provider_name !== '-') {
            $pill.append(
                $('<span/>', { class: 'kcc-availability-field' })
                    .append($('<span/>', { class: 'kcc-availability-field-label', text: terms.providerSingle }))
                    .append($('<span/>', { class: 'kcc-availability-field-value', text: row.provider_name }))
            );
        }

        if (!row.available) {
            $pill.append($('<span/>', { class: 'kcc-availability-time text-danger', text: 'Dolu' }));
            return $pill;
        }

        if (row.is_now && !row.provider_name) {
            $pill.append($('<span/>', { class: 'kcc-availability-time text-success', text: 'Şimdi Boş' }));
        } else {
            $pill.append($('<span/>', { class: 'kcc-availability-time', text: row.is_now ? 'Şimdi' : (row.time + ' Boş') }));
        }

        if (Number.isFinite(row.window_minutes)) {
            $pill.append($('<span/>', { class: 'kcc-availability-window', text: '~' + row.window_minutes + ' dk' }));
        }

        return $pill;
    }

    function renderGroup($container, label, rows, iconClass, renderRowFn) {
        if (!rows || !rows.length) {
            return;
        }
        const $group = $('<div/>', { class: 'kcc-availability-group flex-grow-1' });
        const iconHtml = iconClass ? `<i class="${iconClass} me-1 opacity-75"></i> ` : '';
        $group.append($('<div/>', { class: 'kcc-availability-group-label d-flex align-items-center mb-1' }).html(iconHtml + label));

        const $row = $('<div/>', { class: 'kcc-availability-row d-flex gap-2' });
        rows.forEach((row) => $row.append(renderRowFn(row)));

        $group.append($row);
        $container.append($group);
    }

    function render($container, providerRows, roomRows) {
        $container.empty();
        const terms = getVerticalTerms();

        if (providerRows && providerRows.length) {
            renderGroup($container, terms.providerGroup, providerRows, terms.providerIcon, (r) => renderProviderRow(r, terms));
        }

        if (roomRows && roomRows.length) {
            renderGroup($container, terms.stationGroup, roomRows, terms.stationIcon, (r) => renderStationRow(r, terms));
        }

        if ((!providerRows || !providerRows.length) && (!roomRows || !roomRows.length)) {
            $container.append($('<span/>', { class: 'text-muted small fst-italic py-1', text: 'Müsaitlik bilgisi bulunamadı.' }));
        }
    }

    function pollMount(mount) {
        $.when(
            App.Http.Calendar.getNextAvailability(mount.getProviderId()),
            App.Http.Calendar.getRoomAvailability(),
        )
            .done((providerResponse, roomResponse) => {
                const providerRows = (providerResponse[0] && providerResponse[0].rows) || [];
                const roomRows = (roomResponse[0] && roomResponse[0].rows) || [];
                render(mount.$container, providerRows, roomRows);
            })
            .fail(() => {
                mount.$container.empty().append(
                    $('<span/>', { class: 'text-danger small', text: 'İlk müsaitlik alınamadı.' }),
                );
            });
    }

    function pollAll() {
        mounts.forEach(pollMount);
    }

    function initialize() {
        const $dashboardStrip = $('#next-availability-strip');

        if ($dashboardStrip.length) {
            mounts.push({ $container: $dashboardStrip, getProviderId: () => null });
        }

        if ($('#calendar-page').length) {
            let $calendarStrip = $('#next-availability-widget');
            if (!$calendarStrip.length) {
                $calendarStrip = $('<div/>', {
                    id: 'next-availability-widget',
                    class: 'kcc-availability-card p-3 bg-white rounded-3 shadow-sm border',
                });
                if ($('#next-availability-container').length) {
                    $('#next-availability-container').append($calendarStrip);
                } else if ($('#calendar-filter').length) {
                    $('#calendar-filter').prepend($calendarStrip);
                }
            } else {
                $calendarStrip.addClass('kcc-availability-card p-3 bg-white rounded-3 shadow-sm border');
            }

            mounts.push({ $container: $calendarStrip, getProviderId: getCalendarFilterProviderId });

            $('#select-filter-item').on('change', () => pollMount(mounts[mounts.length - 1]));
        }

        if (!mounts.length) {
            return;
        }

        pollAll();
        setInterval(pollAll, POLL_INTERVAL_MS);
    }

    document.addEventListener('DOMContentLoaded', initialize);

    return {};
})();
